import React, { useState, useMemo, useCallback } from 'react';
import {
  View,
  Text,
  StyleSheet,
  FlatList,
  TextInput,
  TouchableOpacity,
  Platform,
} from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { useRouter } from 'expo-router';
import { Search, Wind, X, ChevronDown, Check, Plus, ArrowUpDown } from 'lucide-react-native';
import Colors from '@/constants/colors';
import { categoryLabels, MountainCategory } from '@/constants/mountains';
import { useSummits } from '@/contexts/SummitContext';
import { useAllMountains } from '@/hooks/useAllMountains';
import MountainCard from '@/components/MountainCard';

const categories: Array<{ key: MountainCategory | 'all'; label: string }> = [
  { key: 'all', label: 'All Peaks' },
  { key: '7summits', label: '7 Summits' },
  { key: '8000m', label: '8000m' },
  { key: '14ers', label: '14ers' },
  { key: 'alps', label: 'Alps' },
  { key: 'andes', label: 'Andes' },
  { key: 'himalaya', label: 'Himalaya' },
  { key: 'other', label: 'World' },
  { key: 'custom', label: 'My Peaks' },
];

type SortOption = 'name' | 'elevation_desc' | 'elevation_asc';

export default function MountainsScreen() {
  const insets = useSafeAreaInsets();
  const router = useRouter();
  const { isSummited } = useSummits();
  const allMountains = useAllMountains();
  const [search, setSearch] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<MountainCategory | 'all'>('all');
  const [sortBy, setSortBy] = useState<SortOption>('elevation_desc');
  const [showSort, setShowSort] = useState(false);
  const [useFeet, setUseFeet] = useState(false);

  const filteredMountains = useMemo(() => {
    let filtered = allMountains;

    if (selectedCategory !== 'all') {
      filtered = filtered.filter((m) => m.category === selectedCategory);
    }

    if (search.trim()) {
      const q = search.toLowerCase().trim();
      filtered = filtered.filter(
        (m) =>
          m.name.toLowerCase().includes(q) ||
          m.country.toLowerCase().includes(q) ||
          m.range.toLowerCase().includes(q)
      );
    }

    switch (sortBy) {
      case 'name':
        return [...filtered].sort((a, b) => a.name.localeCompare(b.name));
      case 'elevation_asc':
        return [...filtered].sort((a, b) => a.elevation - b.elevation);
      case 'elevation_desc':
      default:
        return [...filtered].sort((a, b) => b.elevation - a.elevation);
    }
  }, [search, selectedCategory, sortBy, allMountains]);

  const handleMountainPress = useCallback((id: string) => {
    router.push(`/mountain/${id}` as any);
  }, [router]);

  const handleO2Press = useCallback(() => {
    router.push('/o2-equivalent' as any);
  }, [router]);

  const handleAddMountain = useCallback(() => {
    router.push('/add-mountain' as any);
  }, [router]);

  const renderItem = useCallback(({ item }: { item: typeof allMountains[0] }) => {
    return (
      <MountainCard
        mountain={item}
        isSummited={isSummited(item.id)}
        onPress={() => handleMountainPress(item.id)}
        useFeet={useFeet}
      />
    );
  }, [isSummited, handleMountainPress, useFeet]);

  const sortLabels: Record<SortOption, string> = {
    name: 'Name A-Z',
    elevation_desc: 'Highest First',
    elevation_asc: 'Lowest First',
  };

  return (
    <View style={styles.container}>
      <View style={[styles.header, { paddingTop: insets.top + 8 }]}>
        <View style={styles.titleRow}>
          <Text style={styles.title}>Summit Tracker</Text>
          <View style={styles.titleActions}>
            <TouchableOpacity
              style={styles.addButton}
              onPress={handleAddMountain}
              activeOpacity={0.7}
              testID="add-mountain-button"
            >
              <Plus color={Colors.white} size={18} />
            </TouchableOpacity>
            <TouchableOpacity
              style={styles.o2Button}
              onPress={handleO2Press}
              activeOpacity={0.7}
            >
              <Wind color={Colors.primary} size={16} />
              <Text style={styles.o2Text}>O₂</Text>
            </TouchableOpacity>
          </View>
        </View>

        <View style={styles.searchRow}>
          <View style={styles.searchContainer}>
            <Search color={Colors.textMuted} size={16} />
            <TextInput
              style={styles.searchInput}
              placeholder="Search peaks, countries, ranges..."
              placeholderTextColor={Colors.textMuted}
              value={search}
              onChangeText={setSearch}
            />
            {search.length > 0 && (
              <TouchableOpacity onPress={() => setSearch('')}>
                <X color={Colors.textMuted} size={16} />
              </TouchableOpacity>
            )}
          </View>
        </View>

        <FlatList
          data={categories}
          horizontal
          showsHorizontalScrollIndicator={false}
          keyExtractor={(item) => item.key}
          contentContainerStyle={styles.categoryList}
          renderItem={({ item }) => {
            const isActive = selectedCategory === item.key;
            return (
              <TouchableOpacity
                style={[
                  styles.categoryChip,
                  isActive && styles.categoryChipActive,
                ]}
                onPress={() => setSelectedCategory(item.key)}
                activeOpacity={0.7}
              >
                <Text
                  style={[
                    styles.categoryChipText,
                    isActive && styles.categoryChipTextActive,
                  ]}
                >
                  {item.label}
                </Text>
              </TouchableOpacity>
            );
          }}
        />
      </View>

      {showSort && (
        <View style={styles.sortDropdown}>
          {(Object.keys(sortLabels) as SortOption[]).map((key) => (
            <TouchableOpacity
              key={key}
              style={[styles.sortOption, sortBy === key && styles.sortOptionActive]}
              onPress={() => {
                setSortBy(key);
                setShowSort(false);
              }}
            >
              <Text style={[styles.sortOptionText, sortBy === key && styles.sortOptionTextActive]}>
                {sortLabels[key]}
              </Text>
              {sortBy === key && <Check color={Colors.primary} size={14} />}
            </TouchableOpacity>
          ))}
        </View>
      )}

      <View style={styles.listHeaderRow}>
        <Text style={styles.resultCount}>
          {filteredMountains.length} peak{filteredMountains.length !== 1 ? 's' : ''}
        </Text>
        <View style={styles.listHeaderRight}>
          <TouchableOpacity
            style={styles.sortButton}
            onPress={() => setShowSort(!showSort)}
            activeOpacity={0.7}
          >
            <ChevronDown color={Colors.primary} size={14} />
            <Text style={styles.sortLabel}>{sortLabels[sortBy]}</Text>
          </TouchableOpacity>
          <TouchableOpacity
            style={styles.unitToggleBtn}
            onPress={() => setUseFeet(prev => !prev)}
            activeOpacity={0.7}
            testID="unit-toggle-button"
          >
            <ArrowUpDown color={Colors.primary} size={13} />
            <Text style={styles.unitToggleBtnText}>{useFeet ? 'FT' : 'M'}</Text>
          </TouchableOpacity>
        </View>
      </View>

      <FlatList
        data={filteredMountains}
        keyExtractor={(item) => item.id}
        renderItem={renderItem}
        contentContainerStyle={styles.list}
        showsVerticalScrollIndicator={false}
        initialNumToRender={10}
        maxToRenderPerBatch={10}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: Colors.white,
  },
  header: {
    backgroundColor: Colors.white,
    borderBottomWidth: 1,
    borderBottomColor: Colors.border,
    paddingBottom: 4,
  },
  titleRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    paddingHorizontal: 20,
    marginBottom: 14,
  },
  title: {
    fontSize: 26,
    fontWeight: '700' as const,
    color: Colors.text,
    letterSpacing: -0.5,
  },
  titleActions: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 8,
  },
  addButton: {
    width: 36,
    height: 36,
    borderRadius: 18,
    backgroundColor: Colors.primary,
    justifyContent: 'center',
    alignItems: 'center',
  },
  o2Button: {
    flexDirection: 'row',
    alignItems: 'center',
    backgroundColor: Colors.frost,
    paddingHorizontal: 12,
    paddingVertical: 8,
    borderRadius: 18,
    gap: 4,
    borderWidth: 1,
    borderColor: Colors.border,
  },
  o2Text: {
    color: Colors.primary,
    fontSize: 13,
    fontWeight: '600' as const,
  },
  searchRow: {
    paddingHorizontal: 20,
    marginBottom: 12,
  },
  searchContainer: {
    flexDirection: 'row',
    alignItems: 'center',
    backgroundColor: Colors.frost,
    borderRadius: 10,
    paddingHorizontal: 12,
    gap: 8,
    borderWidth: 1,
    borderColor: Colors.border,
  },
  searchInput: {
    flex: 1,
    color: Colors.text,
    fontSize: 14,
    paddingVertical: Platform.OS === 'web' ? 10 : 11,
  },
  sortDropdown: {
    marginHorizontal: 20,
    backgroundColor: Colors.white,
    borderRadius: 12,
    marginBottom: 4,
    overflow: 'hidden',
    borderWidth: 1,
    borderColor: Colors.border,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.08,
    shadowRadius: 8,
    elevation: 3,
  },
  sortOption: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    paddingHorizontal: 16,
    paddingVertical: 12,
  },
  sortOptionActive: {
    backgroundColor: Colors.frost,
  },
  sortOptionText: {
    color: Colors.textSecondary,
    fontSize: 14,
  },
  sortOptionTextActive: {
    color: Colors.primary,
    fontWeight: '600' as const,
  },
  categoryList: {
    paddingHorizontal: 16,
    gap: 8,
    paddingBottom: 10,
  },
  categoryChip: {
    paddingHorizontal: 16,
    paddingVertical: 7,
    borderRadius: 18,
    backgroundColor: Colors.frost,
    borderWidth: 1,
    borderColor: Colors.border,
  },
  categoryChipActive: {
    backgroundColor: Colors.primary,
    borderColor: Colors.primary,
  },
  categoryChipText: {
    color: Colors.textSecondary,
    fontSize: 13,
    fontWeight: '500' as const,
  },
  categoryChipTextActive: {
    color: Colors.white,
    fontWeight: '600' as const,
  },
  listHeaderRow: {
    flexDirection: 'row' as const,
    alignItems: 'center' as const,
    justifyContent: 'space-between' as const,
    paddingHorizontal: 20,
    paddingTop: 10,
    paddingBottom: 6,
    backgroundColor: Colors.white,
  },
  listHeaderRight: {
    flexDirection: 'row' as const,
    alignItems: 'center' as const,
    gap: 8,
  },
  resultCount: {
    color: Colors.textSecondary,
    fontSize: 12,
    fontWeight: '500' as const,
  },
  sortButton: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 4,
  },
  sortLabel: {
    color: Colors.primary,
    fontSize: 12,
    fontWeight: '600' as const,
  },
  unitToggleBtn: {
    flexDirection: 'row' as const,
    alignItems: 'center' as const,
    backgroundColor: Colors.frost,
    paddingHorizontal: 10,
    paddingVertical: 5,
    borderRadius: 10,
    gap: 4,
    borderWidth: 1,
    borderColor: Colors.border,
  },
  unitToggleBtnText: {
    fontSize: 12,
    fontWeight: '600' as const,
    color: Colors.primary,
  },
  list: {
    paddingBottom: 20,
  },
});

