import { Stack } from 'expo-router';
import { Wind } from 'lucide-react-native';
import Colors from '@/constants/colors';

interface AltitudeRow {
  altitude: number;
  altitudeFt: number;
  o2Percent: number;
  effectiveO2: number;
  zone: string;
  color: string;
}

