    borderRadius: 5,
  },
  legendText: {
    color: Colors.text,
    fontSize: 12,
    fontWeight: '500' as const,
  },
  fallbackContainer: {
    flex: 1,
    backgroundColor: Colors.snow,
  },
  fallbackContent: {
    flex: 1,
    alignItems: 'center',
    paddingHorizontal: 24,
